  ["Stereo module not installed."] = "Стереомодуль не установлен.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "Хуки движка не загрузились, поэтому всё ниже неактивно, а шлем работает в обычном моно-режиме. Либо CyberpunkVR_StereoModuleEnable равен 0, либо существует bin\\x64\\vrport_nostereo.txt. См. строку \"Stereo:\" в cyberpunkvrport.log.",
  ["LEFT"] = "ЛЕВЫЙ",
  ["RIGHT"] = "ПРАВЫЙ",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Стерео активно  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Второго глаза сейчас нет -> оба глаза получают MAIN (моно)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "Ожидаемо в меню и при загрузке. Если так остаётся в игре: компонент VRCAM выключен или vrcam.json указывает камеру, которой нет у сущности игрока.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Отправка стерео выключена -> оба глаза получают MAIN (моно)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "возраст глаза vrcam %u мс  (устарел после %u)   отправок глаза %llu",
  ["vrcam eye: never produced a frame"] = "глаз vrcam: ни одного кадра",
  ["Send VRCAM to the %s EYE"] = "Отправлять VRCAM в %s ГЛАЗ",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Выкл. = старое поведение, MAIN дублируется в оба глаза.\nВкл. = %s глаз получает собственный финальный цвет вида VRCAM —\nто же изображение, что в зеркале на мониторе, — перекодированное в\nsRGB-формат swapchain и масштабированное под размер глаза.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "копий снимка %llu   пропусков %llu   попаданий RTV vrcam %llu",
  ["Eye staleness limit (ms)"] = "Предел устаревания глаза (мс)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Сколько последний кадр VRCAM остаётся пригодным. После этого %s\nглаз переходит на MAIN — один застывший глаз при движущемся другом\nсмотреть гораздо хуже, чем моно.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (следует апскейлеру MAIN, без переключателя)",
  ["ON"] = "ВКЛ",
  ["off"] = "выкл",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "Включён, когда MAIN апскейлит через DLSS: vrcam получает свой\nвьюпорт Streamline и рендерит ниже целевого разрешения.\nВыключен при DLAA / TAA / без апскейлера. Меняется в графических\nнастройках игры, а не здесь.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "Проекция VRCAM как у MAIN  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "Компонент VRCAM  (RTTI Toggle: принудительно ВКЛ/ВЫКЛ)",
  ["component %s   camera %s"] = "компонент %s   камера %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "узлы вида: main %llu   прочие %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "Зеркало VRCAM  (отдельное окно, для записи)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (ассет %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Диагностика",
  ["Compact ADS camera telemetry (in-headset)"] = "Компактная телеметрия камеры ADS (в шлеме)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "Маленькая панель, которая остаётся после закрытия F10 и показывает, что ДВИЖОК сделал с камерой при подъёме прицела:\nсмещение и пик в сантиметрах, вправо/вперёд/вверх в базисе направления, относительно базы, снятой при стрельбе от бедра.\nНа отправку стерео не влияет.",
  ["Telemetry X"] = "Телеметрия X",
  ["Telemetry Y"] = "Телеметрия Y",
  ["Normalised position in the eye image"] = "Нормализованная позиция в изображении глаза",
  ["Stereo logging -> cyberpunkvrport.log"] = "Лог стерео -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "Зафиксированный снимок финала VRCAM",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Выкл. = читать временную цель движка напрямую. Эта цель —\nвыделение frame graph, которое позже переиспользует другой проход, из-за\nчего картинка мигала светлым/тёмным. Оставьте включённым.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "Снимок на узле тонмаппинга вместо RenderFinal2D",
  ["Node CPU profiler  (per-node self+incl ms)"] = "CPU-профайлер узлов  (собств.+вкл. мс на узел)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "кадр %.2f мс   диспетчер: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Аудит узлов -> лог  (сбрасывает окно)",
  ["top %d by self ms/frame   (main | vrcam)"] = "топ %d по собств. мс/кадр   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Вождение — руки на руле",
  ["Grab the wheel with the grips"] = "Хватать руль грипами",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "Во время ВОЖДЕНИЯ поднесите руку туда, где анимация держит\nруль (или руль мотоцикла), и сожмите грип: рука передаётся\nродной анимации игры — ладонь на руле, пальцы обхватывают\nего — вместо следования за контроллером. Отпустите грип, и она\nвернётся к вашей руке.\n\nРуки независимы: держите руль одной, а в другой — оружие.\nПока рука на руле, этот грип больше ничего не делает (не\nдостаёт из кобуры, не хватает магазин).",
  ["Grab radius (m)"] = "Радиус захвата (м)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Насколько близко рука должна быть к анимированной руке, чтобы\nгрип считался захватом руля. Больше = проще поймать руль,\nкоторого не видно; слишком много — и любой грип в машине хватает руль.",
  ["Car full lock at (deg)"] = "Полный поворот руля при (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Чувствительность руля: поворот руки от точки захвата до упора.\nОдна рука использует ступицу, откалиброванную в месте захвата; две — линию между ними.\nДобавление или отпускание руки сохраняет текущий поворот.\n180 = пол-оборота до упора в каждую сторону (по умолчанию). Меньше = чувствительнее.\nРуль в салоне имеет вдвое больший ход, чем родной; угол колёс не меняется.\nХод за упором сохраняет то же нейтральное положение.",
  ["Steering deadzone (deg)"] = "Мёртвая зона руля (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Наклон вокруг центра, который вообще не рулит.\nУвеличьте, если машину уводит, пока вы держите руль прямо;\nкаждый градус здесь — градус мёртвого руля от центра.\nПолный диапазон всё равно заканчивается на «Полный поворот руля при», поэтому\nрасширение мёртвой зоны не даёт рывка руления.",
  ["Steering prediction"] = "Предсказание руления",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "Мягко предугадывает продолжение поворота по недавнему движению руки.\nНе более 8 мс и 0.5°; нейтраль не меняется.\nПредсказание останавливается при паузе, смене направления или хвата.\nВыкл. по умолчанию. Начало поворота предугадать нельзя.",
  ["Prediction horizon (ms)"] = "Горизонт предсказания (мс)",
  ["Horn -- hand on the wheel hub"] = "Клаксон — рука на центре руля",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "Во время ВОЖДЕНИЯ положите руку на СЕРЕДИНУ руля — туда, где\nбьют по настоящему клаксону, — и машина сигналит, пока рука там.\nГрип не нужен; рука, которая ДЕРЖИТ руль, никогда не сигналит.",
  ["Horn hub radius (m)"] = "Радиус центра руля (м)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Насколько близко к центру руля рука считается на ступице.\nБольше = проще найти клаксон не глядя; слишком много —\nи зона дойдёт до обода, и каждый захват будет сигналить.",
  ["Trigger fires the gun while driving"] = "Курок стреляет во время вождения",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Достаньте оружие на месте водителя, и ПРАВЫЙ КУРОК перестаёт быть\nгазом и становится выстрелом: ведите левой рукой на руле и\nстреляйте правой.\n\nГаз ФИКСИРУЕТСЯ на том уровне, каким был при выхватывании оружия, поэтому\nмашина продолжает ехать, а ЛЕВЫЙ СТИК вперёд/назад подстраивает скорость, пока\nвы стреляете. Уберите оружие, и курок снова станет газом.\n\nПока оружие в руках, вперёд/назад левого стика занято\nподстройкой: никаких наклонов / раскачки и жеста автовождения, пока не уберёте оружие.",
  ["Throttle trim rate (/s)"] = "Скорость подстройки газа (/с)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "Какую долю полного хода газа левый стик добавляет или\nубирает за секунду, пока оружие в руках.\n0.5 = две секунды удержания от холостого до полного газа.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "вождение %d   на руле  L %d R %d   хват  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "руль  %+.1f°  ->  стик %+.2f     клаксон  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "СМЕЩЕНИЕ КАМЕРЫ СИДЯ",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "Смещения головы на вкладке ОБЩИЕ — калибровка стоя. Сидя родная камера\nтранспорта уже там, где нужно, — поэтому порт отключает\nсвои две автоподстройки в транспорте, — и смещение для стоя уводит вид\nс сиденья, вместо того чтобы исправлять его.\n\nЭти три значения добавляются к ползункам головы, пока вы в транспорте, и\nигнорируются, как только вы выходите, так что машину и улицу можно настроить\nотдельно. Ноль = машина сохраняет ровно то смещение, что есть сейчас.",
  ["Car Head X right"] = "Голова в машине X вправо",
  ["Car Head Y forward"] = "Голова в машине Y вперёд",
  ["Car Head Z up"] = "Голова в машине Z вверх",
