  ["Glow"] = "Свечение",
  ["INTERACTIONS / DIALOGS"] = "ВЗАИМОДЕЙСТВИЯ / ДИАЛОГИ",
  ["World-space interactions / dialogs"] = "Взаимодействия / диалоги в мире",
  ["Interaction free-look cone"] = "Конус свободного обзора взаимодействий",
  ["Loot free-look cone"] = "Конус свободного обзора добычи",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "Используется, пока видны панель добычи и описание предмета. По умолчанию: 10°.",
  ["Interaction distance"] = "Расстояние взаимодействий",
  ["Interaction FOV"] = "FOV взаимодействий",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "Подсказки взаимодействий и варианты диалогов делят эту панель. Она следует только за пределами конуса; без отложенного догона в покое.",
  ["Element"] = "Элемент",
  ["Not currently visible in gameplay; settings are still saved."] = "Сейчас не виден в игре; настройки всё равно сохраняются.",
  ["Show element"] = "Показывать элемент",
  ["Horizontal offset"] = "Смещение по горизонтали",
  ["Vertical offset"] = "Смещение по вертикали",
  ["Size"] = "Размер",
  ["Opacity"] = "Непрозрачность",
  ["Reset element"] = "Сбросить элемент",
  ["Reset all elements"] = "Сбросить все элементы",
  ["CONTROLS"] = "УПРАВЛЕНИЕ",
  ["DRIVING"] = "ВОЖДЕНИЕ",
  ["BINDINGS"] = "НАЗНАЧЕНИЯ",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Передвижение, прицеливание и физические взаимодействия.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "Прицел рукой  (выкл. = раздельный прицел головой VR)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "ВКЛ (прицел рукой): контроллер направляет оружие, а VRIK управляет руками.\nВЫКЛ (раздельный прицел головой VR): ОРУЖИЕ следует за головой, игра\nсохраняет его положение и анимации ADS, а VRIK отпускает\nруку с оружием. В обоих режимах выстрел идёт из настоящего дула — и для пуль,\nи для снарядов, — а свободный обзор при прицеливании сохраняется.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Лазерная точка прицела (куда попадёт пуля)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "Красная точка, проецируемая по реальному направлению дула через\nкамеру игры, — показывает точно, куда полетит пуля.",
  ["Controller vibration"] = "Вибрация контроллеров",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Отдача в руки: каждый выстрел по классу оружия (пистолет, винтовка, дробовик, снайперка),\nблок и парирование в ближнем бою, блок и отражение пуль, касание элемента пояса,\nвыдёргивание чеки гранаты. Хват двумя руками: обе руки; одной рукой: одна.",
  ["Vibration strength"] = "Сила вибрации",
  ["Enable VR -> XInput merge"] = "Включить слияние VR -> XInput",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Объединяет (OR) состояние VR-контроллеров с геймпадом XInput 0 при каждом опросе.\nВыкл. = игра видит только физический геймпад / ничего.",
  ["Weapon holsters (reach + right grip)"] = "Кобуры оружия (дотянуться + правый грип)",
  ["Immersive holsters"] = "Иммерсивные кобуры",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "ВКЛ  - оружие выбирается по ВИДИМОЙ кобуре, к которой вы тянетесь:\n      над правым плечом = основное оружие (винтовка / снайперка),\n      бедро с катаной = ближний бой, бедро с пистолетом = пистолет.\nВЫКЛ - видимые кобуры не учитываются, фиксированный слот на зону:\n      над плечом = EquipmentSlot1, правое бедро = Slot2, левое бедро = Slot3.\nДотянитесь до зоны и сожмите ПРАВЫЙ грип, чтобы достать / убрать оружие.",
  ["Locomotion direction"] = "Направление передвижения",
  ["Analog movement"] = "Аналоговое передвижение",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "Вкл.: скорость следует ходу левого стика. Выкл.: текущее движение с фиксированной скоростью (по умолчанию).\nУправление транспортом сохраняет прежний отклик.",
  ["Left stick deadzone"] = "Мёртвая зона левого стика",
  ["Right stick deadzone"] = "Мёртвая зона правого стика",
  ["Full input threshold"] = "Порог полного ввода",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Ход стика, дающий полный аналоговый ввод и включающий спринт, рывок и присед.\nРабочий ход между мёртвой зоной и этим порогом соответствует 0-100%%.",
  ["Game (camera)"] = "Игра (камера)",
  ["HMD (head)"] = "HMD (голова)",
  ["Left hand"] = "Левая рука",
  ["Right hand"] = "Правая рука",
  ["Move source"] = "Источник направления",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Игра     - левый стик ведёт туда, куда смотрит камера (как в оригинале).\nHMD      - левый стик ведёт туда, куда смотрит шлем.\nЛевая/правая рука - ведёт туда, куда указывает выбранный контроллер.\nТранспорт всегда сохраняет направление игры.",
  ["Breaststroke swimming"] = "Плавание брассом",
  ["Physical crouch"] = "Физический присед",
  ["Physical crouch depth"] = "Глубина физического приседа",
  ["%.0f cm"] = "%.0f см",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Потеря высоты после измеренного наклона. Если выпрямиться, физический присед снимается.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "В воде: вытяните обе руки вперёд, разведите в стороны и потяните назад.\nДвижение начинается во время гребка. Мягкие гребки — обычное плавание; быстрые — ускорение.\nВы плывёте туда, куда смотрит шлем, в том числе вверх/вниз; стик не нужен.\nЧтобы всплыть, поднимите разведённые руки до груди и опустите обе вниз.\nПовторяйте гребки, чтобы плыть дальше. Потяните левый стик назад, чтобы остановиться.",
  ["Ladder grip climbing"] = "Лазание по лестнице грипами",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Возьмитесь за боковую стойку или ступеньку. Тяните руку вниз, чтобы лезть вверх,\nили ведите её вверх, чтобы спускаться. Отпустите, чтобы остановиться. Таз и ноги остаются на лестнице.",
  ["Auto finish near ladder top"] = "Автозавершение у верха лестницы",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "После подтягивания у самого верха подъём завершается, даже если грипы отпущены.\nДвиньте стик или толкните удерживающую руку вверх, чтобы отменить.",
  ["Ladder finish distance"] = "Расстояние завершения подъёма",
  ["Turning (right stick)"] = "Поворот (правый стик)",
  ["Snap turn"] = "Поворот рывками",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "Превращает ось X правого стика в отдельные рывки поворота\nвместо плавного вращения. Помогает при укачивании.",
  ["Snap angle"] = "Угол рывка",
  ["STEREO"] = "СТЕРЕО",
  ["PERFORMANCE"] = "ПРОИЗВОДИТЕЛЬНОСТЬ",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Как в игре",
  ["Off (higher FPS)"] = "Выкл. (выше FPS)",
  ["On (lower latency)"] = "Вкл. (ниже задержка)",
  ["On + Boost"] = "Вкл. + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "Выкл. может поднять загрузку GPU и FPS, но может увеличить задержку ввода.",
  ["On"] = "Вкл.",
  ["Waiting for renderer"] = "Ожидание рендерера",
  ["Applied: %s"] = "Применено: %s",
  ["STEREO VIEW"] = "СТЕРЕОВИД",
  ["Mono mode"] = "Моно-режим",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Одна картинка для обоих глаз, отрисованная один раз из центра головы:\nбез глубины, максимум кадров. Engine stereo и второй вид выключены.",
  ["Restart the game to apply"] = "Перезапустите игру, чтобы применить",
  ["Motion prediction (ms)"] = "Предсказание движения (мс)",
  ["%.1f ms"] = "%.1f мс",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Предсказывает позу головы вперёд на столько мс по скорости\nголовы, скрывая задержку от рендера до фотонов. 0 = выкл.\nУвеличивайте, пока движение не станет отзывчивым без перелёта.",
  ["Stereo separation x"] = "Стереоразнос x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Личная подстройка авто-IPD. 1.0 = откалиброванный естественный\nразнос, автомасштабируемый под IPD среды шлема. Сдвигайте\n0.8-1.2 по вкусу; 3-5x преувеличивает глубину и делает\nчередование глаз заметным на плоском мониторе для проверки.",
  ["World scale"] = "Масштаб мира",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Масштабирует разнос глаз И перемещение головы вместе.\nУменьшите (напр. 0.8), чтобы мир казался\nБОЛЬШЕ, а вы — меньше; увеличьте, чтобы мир уменьшился. Используйте, если Ви\nи NPC кажутся слишком большими.",
  ["IPD scale"] = "Масштаб IPD",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Множитель разноса глаз к IPD среды. 1.0 = нейтральная\nбаза (+-0.033 м на типичном шлеме).\nВлияет на стереоглубину (диорама или великан), а НЕ на монокулярный размер.",
  ["Reuse last clean frame"] = "Повтор последнего чистого кадра",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "На устаревших тиках повторно отправляет последний чистый захваченный глаз и даёт\nкомпозитору его репроецировать вместо повторного варпа устаревшего\nсодержимого. Может снизить частоту отправки\nдо частоты захвата. Выкл. = всегда варпить устаревший глаз.",
  ["Asymmetric projection"] = "Асимметричная проекция",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "ВКЛ: каждый глаз рендерит ровно своё смещённое окно линзы\n(больше панели в деле, квадратные пиксели).\nВЫКЛ: симметричная пирамида по самому широкому полууглу.",
  ["AVATAR"] = "АВАТАР",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "VR-команды и действия игры по умолчанию. Названия кнопок по схеме Touch / Xbox; действия игры используют ваши назначения контроллера.",
  ["LEFT STICK"] = "ЛЕВЫЙ СТИК",
  ["Move. Hold fully forward for 0.2 seconds to sprint."] = "Движение. Держите полностью вперёд 0.2 секунды для спринта.",
